# Proper duplicate detection
demo4_unique_rows = []
seen = set()
for line in demo4_output_lines.strip().split('\n'):
    row = tuple(int(x) for x in line.split())
    if row not in seen:
        seen.add(row)
        demo4_unique_rows.append(row)

print(f"Number of unique rows: {len(demo4_unique_rows)}")
for i, row in enumerate(demo4_unique_rows):
    print(f"  Unique row {i}: {list(row)}")

print()
print("Row counts by value:")
row_counts = {}
for line in demo4_output_lines.strip().split('\n'):
    row = tuple(int(x) for x in line.split())
    if row not in row_counts:
        row_counts[row] = 0
    row_counts[row] += 1
for row, count in row_counts.items():
    row_list = list(row)
    print(f"  {row_list}: appears {count} time(s)")
